<section class="support-guest-card support-guest-conversation">
    <p class="support-kicker">Verdant · Customer support</p><p><span class="support-state support-state--<?= $e($thread['enquiry_state']) ?>"><?= $e(ucfirst($thread['enquiry_state'])) ?></span></p>
    <h1><?= $e($thread['subject']) ?></h1><p>Private conversation with Verdant support</p>
    <ol class="support-messages" aria-label="Conversation history">
        <?php foreach ($thread['messages'] as $message): ?><li class="support-message support-message--<?= $e($message['author_kind']) ?>"><header><strong><?= $message['author_kind'] === 'admin' ? 'Verdant support' : 'You' ?></strong><time><?= $e($message['created_at']) ?></time></header><p><?= nl2br($e($message['body']), false) ?></p></li><?php endforeach ?>
    </ol>
    <?php if ($thread['messages_pages'] > 1): ?><nav class="support-pagination" aria-label="Message history pages"><span>Page <?= $e($thread['messages_page']) ?> of <?= $e($thread['messages_pages']) ?></span><?php if ($thread['messages_page'] < $thread['messages_pages']): ?><a href="/support/guest?id=<?= $e($thread['enquiry_id']) ?>&page=<?= $e($thread['messages_page'] + 1) ?>">Older messages</a><?php endif ?><?php if ($thread['messages_page'] > 1): ?><a href="/support/guest?id=<?= $e($thread['enquiry_id']) ?>&page=<?= $e($thread['messages_page'] - 1) ?>">Newer messages</a><?php endif ?></nav><?php endif ?>
    <form method="post" action="/support/guest/reply" class="support-reply-form"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="enquiry_id" value="<?= $e($thread['enquiry_id']) ?>"><input type="hidden" name="submission_key" value="<?= $e($replyKey) ?>"><?php if (!empty($replyFeedback['error'])): ?><p role="alert"><?= $e($replyFeedback['error']) ?></p><?php endif ?><label for="guest-support-reply">Your reply</label><textarea id="guest-support-reply" name="body" rows="6" maxlength="5000" required><?= $e($replyFeedback['body'] ?? '') ?></textarea><button type="submit">Send reply</button></form>
</section>
